const campaigns=$input.first().json||[];
const recent=campaigns.filter(c=>new Date(c.created_date)>new Date(Date.now()-7*86400000));
const results=[];
for(const c of recent){
  const sent=c.stats?.total||0;
  const opened=c.stats?.opened||0;
  const clicked=c.stats?.clicked||0;
  const creds=c.stats?.submitted_data||0;
  results.push({campaign_id:c.id,campaign_name:c.name,sent,opened,clicked,creds,
    click_rate:sent>0?Math.round((clicked/sent)*100):0,
    cred_rate:sent>0?Math.round((creds/sent)*100):0,
    needs_training:clicked>0});
}
const avg_click_rate=results.length>0?Math.round(results.reduce((s,r)=>s+r.click_rate,0)/results.length):0;
return[{json:{campaigns:results,total_campaigns:results.length,avg_click_rate,
  high_risk:results.filter(r=>r.click_rate>20),analysed_at:new Date().toISOString()}}];

